def scan(path, cls, name):
    lines=Path(path).read_text(encoding="utf-8").splitlines()
    if name is None:
        pat=re.compile(r"^class\s+"+re.escape(cls)+r"\b")
        for i,line in enumerate(lines,1):
            if pat.match(line):
                return i,line.strip()
        return None
    if cls is None:
        pat=re.compile(r"^def\s+"+re.escape(name)+r"\s*\(")
        for i,line in enumerate(lines,1):
            if pat.match(line):
                return i,line.strip()
        return None
    cpat=re.compile(r"^class\s+"+re.escape(cls)+r"\b")
    mpat=re.compile(r"^\s+def\s+"+re.escape(name)+r"\s*\(")
    inside=False
    for i,line in enumerate(lines,1):
        if cpat.match(line):
            inside=True
            continue
        if inside and line and not line[0].isspace():
            inside=False
        if inside and mpat.match(line):
            return i,line.strip()
    return None
